
public class ex3_f {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		
		// Parte 1: Decrescente (de 1..5 até 1)
		for (int i = 5; i >= 1; i--) {
		    for (int j = 1; j <= i; j++) {
		        System.out.print(j + " ");
		    }
		    System.out.println();
		}

	
		}
		}
		
	


